<?php
namespace App\Livewire\Panel;
use App\Models\Book; use Illuminate\Support\Str; use Livewire\Component; use Livewire\WithFileUploads; use Livewire\Features\SupportFileUploads\TemporaryUploadedFile;
class BooksManager extends Component { use WithFileUploads; public ?int $editingId=null; public string $title='',$description='',$author='',$publishedOn='',$price=''; public bool $published=false; public ?TemporaryUploadedFile $cover=null,$document=null;
 public function edit(int $id):void{$b=Book::findOrFail($id);$this->editingId=$id;$this->title=$b->title;$this->description=$b->description;$this->author=$b->author;$this->publishedOn=$b->published_on->format('Y-m-d');$this->price=(string)$b->price;$this->published=$b->is_published;}
 public function save():void{$data=$this->validate(['title'=>['required','max:180'],'description'=>['required','max:4000'],'author'=>['required','max:150'],'publishedOn'=>['required','date'],'price'=>['required','integer','min:1'],'published'=>['boolean'],'cover'=>[$this->editingId?'nullable':'required','image','max:4096'],'document'=>[$this->editingId?'nullable':'required','file','mimes:pdf','max:20480']]);$book=$this->editingId?Book::findOrFail($this->editingId):new Book();$book->fill(['title'=>$data['title'],'description'=>$data['description'],'author'=>$data['author'],'published_on'=>$data['publishedOn'],'price'=>$data['price'],'is_published'=>$data['published'],'slug'=>$book->exists?$book->slug:Str::slug($data['title']).'-'.Str::lower(Str::random(6))]);if($this->cover)$book->cover_path=$this->cover->store('books/covers','public');if($this->document)$book->document_path=$this->document->store('books/source','local');$book->save();$this->reset();session()->flash('panel_success','Livre enregistré.');}
 public function render(){return view('livewire.panel.books-manager',['books'=>Book::latest()->get()]);}}
